INSERT INTO remedies (id, name, condition, condition_label, description, instructions, timing, tracking_note, evidence, caution, premium) VALUES
('protein_meals_pcos', 'Balanced, Protein-Forward Meals', 'pcos_symptoms', 'PCOS Symptom Support', 'Pairing carbohydrates with protein and fibre slows sugar absorption, which helps steady the insulin swings often linked to PCOS.', 'Build each meal around a protein (eggs, fish, beans), vegetables, and a slow carb like oats, beans, or whole grains.', 'Every meal.', 'Note energy, cravings, and cycle length over 3 months.', 'Blood-sugar stability is a standard first-line lifestyle approach in PCOS management.', 'PCOS needs a doctor''s diagnosis. These are supportive habits, not a treatment.', false),
('movement_pcos', 'Regular, Moderate Movement', 'pcos_symptoms', 'PCOS Symptom Support', 'Walking and strength work improve insulin sensitivity, which can ease several PCOS symptoms.', 'Aim for a brisk walk or light strength session most days of the week, whatever length you can manage.', 'Most days.', 'Log activity alongside energy and mood weekly.', 'Exercise is well documented to improve insulin sensitivity in women with PCOS.', NULL, true),
('track_for_doctor_pcos', 'Track Your Cycle and Symptoms for Your Doctor', 'pcos_symptoms', 'PCOS Symptom Support', 'A clear record of period dates, skin, hair changes, and weight helps a doctor spot PCOS patterns faster.', 'Log period start dates, how long they last, and any hair, skin, or weight changes. Bring the summary to your appointment.', 'Ongoing.', 'Use /docprep to generate a summary.', 'Cycle and symptom history is central to how PCOS is assessed.', 'See a doctor if you go 3 months or more without a period.', true),
('sleep_schedule_hormones', 'Keep a Steady Sleep Schedule', 'hormonal_imbalance', 'Hormonal Imbalance Signs', 'Irregular sleep disrupts cortisol and appetite hormones, which can worsen mood, skin, and cycle changes.', 'Go to bed and wake at similar times daily, and keep screens away for the last 30 minutes before bed.', 'Nightly.', 'Log sleep hours alongside mood and cycle changes.', 'Sleep timing strongly influences cortisol, insulin, and reproductive hormone rhythms.', NULL, false),
('stress_downshift_hormones', 'Build in a Daily Stress Downshift', 'hormonal_imbalance', 'Hormonal Imbalance Signs', 'Chronic stress keeps cortisol high, which can throw off ovulation and worsen PMS.', 'Take 5-10 minutes daily for slow breathing, a walk, or stretching, ideally at the same time each day.', 'Daily.', 'Rate stress and PMS severity weekly.', 'Chronic stress affects the hormonal signals that control the menstrual cycle.', NULL, true),
('baseline_checkup_hormones', 'Get a Baseline Check-up', 'hormonal_imbalance', 'Hormonal Imbalance Signs', 'Symptoms like irregular periods, acne, fatigue, and mood swings have many possible causes, and a blood test can narrow them down.', 'Ask a doctor about checking thyroid function, iron, vitamin D, and other relevant hormones based on your symptoms.', 'When symptoms persist for 2-3 cycles.', 'Bring a symptom and cycle log.', 'Blood tests are how hormone-related causes are actually identified.', 'Avoid self-prescribing supplements for suspected hormone issues without testing.', true),
('gentle_removal_hair', 'Choose a Gentle Removal Method', 'excess_facial_hair', 'Excess Facial & Body Hair', 'Shaving does not make hair grow back thicker, but harsh methods can cause irritation and ingrown hairs.', 'Try threading, gentle shaving, or trimming and moisturize afterwards.', 'As needed.', 'Note which method causes the least irritation.', 'Skin irritation, not thickness, is the main downside of frequent removal.', 'Avoid waxing over irritated or broken skin.', false),
('spearmint_tea_hair', 'Spearmint Tea', 'excess_facial_hair', 'Excess Facial & Body Hair', 'Small studies suggest spearmint tea may lower free testosterone modestly in women with excess hair growth.', 'Drink 1-2 cups of spearmint tea daily for a few weeks and see if you notice changes.', 'Daily.', 'Track hair growth monthly with photos.', 'Small trials in women with PCOS-type hair growth found modest reductions in androgen levels.', 'Evidence is limited. Skip if pregnant or breastfeeding unless your doctor agrees.', true),
('track_onset_hair', 'Note When It Started and Tell Your Doctor', 'excess_facial_hair', 'Excess Facial & Body Hair', 'New or fast-growing facial hair can be linked to hormone changes like PCOS, and timing helps a doctor work out why.', 'Note when the growth began, where it is, and any other changes such as acne or irregular periods.', 'Once, then update as it changes.', 'Photograph monthly.', 'Onset and speed of growth help doctors tell common causes apart.', 'Sudden, rapid growth with a deepening voice needs prompt medical review.', true),
('gentle_care_neck_patches', 'Gentle Exfoliation and Moisturizing', 'dark_neck_patches', 'Dark, Velvety Neck & Skin-Fold Patches', 'Thickened, darker skin softens with gentle care, though the patches usually fade only when the underlying cause is addressed.', 'Use a mild exfoliant twice a week and moisturize daily. Avoid harsh scrubbing.', '2x weekly plus daily moisturizer.', 'Photograph monthly.', 'Gentle care improves texture and appearance of these patches.', 'Do not scrub hard or bleach the skin.', false),
('cut_sugar_neck_patches', 'Cut Back on Sugary Drinks and Refined Carbs', 'dark_neck_patches', 'Dark, Velvety Neck & Skin-Fold Patches', 'These patches are often linked to higher insulin levels, and lowering sugar swings can help.', 'Swap sugary drinks for water or unsweetened tea, and choose whole grains over refined ones where you can.', 'Daily.', 'Photograph monthly and note energy and cravings.', 'Lower blood-sugar spikes are associated with improvement in insulin-related skin changes.', NULL, true),
('ask_blood_sugar_neck_patches', 'Ask About a Blood Sugar Test', 'dark_neck_patches', 'Dark, Velvety Neck & Skin-Fold Patches', 'Dark velvety patches can be an early sign of insulin resistance, which is worth checking early.', 'Ask your doctor for a simple fasting glucose or HbA1c test.', 'Soon, then as advised.', 'Note when the patches first appeared.', 'Doctors use these patches as a visible clue to check insulin resistance.', 'Only a blood test can confirm the cause. Do not self-diagnose.', true),
('protein_fibre_weight', 'Prioritize Protein and Fibre', 'hormonal_weight_gain', 'Hormonal Weight Gain & Belly Fat', 'Protein and fibre keep you fuller for longer and steady blood sugar, which helps when hormones are driving hunger.', 'Include a protein and a vegetable or fibre-rich food at each meal.', 'Every meal.', 'Track hunger and energy for two weeks.', 'Higher-protein, higher-fibre meals improve fullness signals.', 'Avoid crash diets. They tend to backfire hormonally.', false),
('strength_training_weight', 'Strength Training Twice a Week', 'hormonal_weight_gain', 'Hormonal Weight Gain & Belly Fat', 'Building muscle improves insulin sensitivity and supports a steadier metabolism.', 'Do two short strength sessions weekly using bodyweight, bands, or weights.', '2x weekly.', 'Note strength and energy rather than only the scale.', 'Resistance training improves insulin sensitivity and body composition.', NULL, true),
('sleep_stress_weight', 'Check Sleep and Stress', 'hormonal_weight_gain', 'Hormonal Weight Gain & Belly Fat', 'Poor sleep and high stress raise hunger hormones and encourage fat storage around the middle.', 'Aim for a consistent sleep schedule and one daily stress-reducing habit.', 'Daily.', 'Log sleep and hunger together for a week.', 'Sleep loss and chronic stress are linked to increased appetite and abdominal weight.', 'If weight changes suddenly without a clear reason, see a doctor.', true),
('note_pattern_thyroid', 'Note the Pattern for 2-4 Weeks', 'thyroid_symptoms', 'Possible Sluggish Thyroid Signs', 'Feeling cold, tired, dry-skinned, and constipated together can point towards a sluggish thyroid, and a clear pattern helps a doctor.', 'Note fatigue, feeling cold, dry skin, hair changes, constipation, and weight changes daily for a few weeks.', 'Daily for 2-4 weeks.', 'Bring the notes to your appointment.', 'Symptom clusters guide whether thyroid testing is worthwhile.', 'These symptoms overlap with many conditions. Only a blood test can tell.', false),
('iodine_foods_thyroid', 'Include Iodine- and Selenium-Rich Foods', 'thyroid_symptoms', 'Possible Sluggish Thyroid Signs', 'The thyroid uses iodine and selenium to make hormones, and both are found in everyday foods.', 'Include fish, eggs, dairy, or a few Brazil nuts in your regular meals.', 'Regularly.', 'Track energy over a month.', 'Iodine and selenium are essential nutrients for thyroid hormone production.', 'Do not take iodine supplements unless a doctor advises it. Too much can worsen thyroid problems.', true),
('ask_thyroid_test', 'Ask for a Thyroid Blood Test', 'thyroid_symptoms', 'Possible Sluggish Thyroid Signs', 'A simple TSH blood test is the standard way to check thyroid function.', 'Ask your doctor for a TSH test and mention your symptom notes.', 'When symptoms last more than a few weeks.', 'Note when you last had it checked.', 'TSH testing is the first-line test for thyroid problems.', NULL, true),
('heat_endo', 'Heat Therapy', 'endometriosis_pain', 'Endometriosis-Type Pain', 'Heat relaxes tight pelvic muscles and eases the deep cramping often described with endometriosis.', 'Apply a warm heat pad or hot water bottle to your lower belly for 15-20 minutes.', 'During pain flares.', 'Rate pain before and after.', 'Heat therapy is a widely used, effective comfort measure for pelvic pain.', 'Never place heat directly on skin. Use a cloth barrier.', false),
('anti_inflammatory_endo', 'Anti-Inflammatory Eating', 'endometriosis_pain', 'Endometriosis-Type Pain', 'Foods rich in omega-3s, fibre, and antioxidants may help reduce inflammation-related pain over time.', 'Include oily fish, leafy greens, berries, and nuts, and cut back on heavily processed foods.', 'Daily, as a long-term habit.', 'Compare pain levels across cycles.', 'Diet patterns high in anti-inflammatory foods are associated with lower pain in some studies.', 'Diet does not replace medical care for endometriosis.', true),
('pelvic_stretch_endo', 'Gentle Pelvic Stretching', 'endometriosis_pain', 'Endometriosis-Type Pain', 'Slow stretches such as child''s pose ease tension in the pelvic floor and lower back.', 'Try child''s pose or knees-to-chest for 1-2 minutes, breathing slowly.', 'When pain builds, or daily.', 'Note relief afterwards.', 'Gentle stretching helps relax muscles that tighten in response to pelvic pain.', 'Severe pain, pain with sex, or pain that disrupts life deserves a doctor visit. Endometriosis is often underdiagnosed.', true),
('track_bleeding_fibroid', 'Track How Much You Bleed', 'fibroid_symptoms', 'Fibroid-Related Heavy Bleeding & Pelvic Pressure', 'Recording how heavy your bleeding is gives a doctor concrete information about possible fibroids.', 'Note how many pads or cups you fill each day and any clots larger than a coin.', 'Every period.', 'Use /log flow entries each day.', 'Bleeding volume is a key measure doctors use to assess fibroid symptoms.', 'Soaking through a pad every hour for several hours needs urgent medical care.', false),
('iron_vitc_fibroid', 'Iron-Rich Foods with Vitamin C', 'fibroid_symptoms', 'Fibroid-Related Heavy Bleeding & Pelvic Pressure', 'Heavy bleeding depletes iron, and vitamin C helps your body absorb it from food.', 'Pair beans, leafy greens, or lean meat with citrus, tomatoes, or peppers.', 'Daily, especially around your period.', 'Track energy across cycles.', 'Vitamin C improves absorption of plant-based iron.', 'Persistent fatigue with heavy periods deserves an iron blood test.', true),
('warm_compress_fibroid', 'Warm Compress for Pelvic Pressure', 'fibroid_symptoms', 'Fibroid-Related Heavy Bleeding & Pelvic Pressure', 'Warmth eases the dull heaviness and pressure some people feel low in the belly.', 'Place a warm compress on your lower abdomen for 15-20 minutes.', 'As needed.', 'Rate pressure before and after.', 'Heat relaxes the muscles around the pelvis and reduces the sensation of pressure.', 'Sudden, severe pelvic pain needs medical attention.', true),
('track_changes_perimeno', 'Track Symptoms and Cycle Changes', 'perimenopause_symptoms', 'Perimenopause Changes', 'Perimenopause can bring shifting cycle lengths, hot flashes, sleep changes, and mood swings, and a log shows the pattern.', 'Note cycle dates, hot flashes, sleep quality, and mood in Ava for a few months.', 'Ongoing.', 'Use /log daily.', 'Symptom tracking helps distinguish perimenopause from other causes.', 'Bleeding after 12 months without a period, or very heavy bleeding, needs a doctor.', false),
('cool_layers_perimeno', 'Dress in Layers and Keep Cool', 'perimenopause_symptoms', 'Perimenopause Changes', 'Being able to cool down quickly reduces the disruption of sudden heat surges.', 'Wear breathable layers, keep a fan handy, and sip cool water.', 'Daily.', 'Note triggers like spicy food or stress.', 'Layering and cooling are standard comfort measures for vasomotor symptoms.', NULL, true),
('weight_bearing_perimeno', 'Weight-Bearing and Strength Exercise', 'perimenopause_symptoms', 'Perimenopause Changes', 'Falling estrogen affects bone density, and resistance exercise helps protect bones and muscle.', 'Include walking, dancing, or strength work several times a week.', 'Several times weekly.', 'Track energy and sleep.', 'Weight-bearing exercise supports bone density during hormonal transition.', NULL, true),
('cool_bedroom_sweats', 'Cool Bedroom and Breathable Bedding', 'night_sweats', 'Night Sweats', 'A cooler sleeping environment lowers the chance of overheating and drenching sweats.', 'Keep the room cool, use cotton or bamboo bedding, and layer covers you can peel off.', 'Nightly.', 'Note how many nights you wake sweating.', 'Lower sleeping temperatures reduce night sweats and improve sleep.', NULL, false),
('evening_triggers_sweats', 'Avoid Evening Triggers', 'night_sweats', 'Night Sweats', 'Alcohol, caffeine, and spicy food can bring on night sweats for some people.', 'Try avoiding these in the 3-4 hours before bed and see if it changes.', 'Evenings.', 'Log triggers and sweats together.', 'Common vasomotor triggers include alcohol, caffeine, and spicy foods.', NULL, true),
('sleepwear_sweats', 'Keep Light Sleepwear and Water Nearby', 'night_sweats', 'Night Sweats', 'Being prepared makes waking up sweaty less disruptive to your sleep.', 'Wear loose cotton sleepwear, keep a spare set and a glass of cool water by the bed.', 'Nightly.', 'Track sleep quality.', 'Comfort measures help preserve sleep when sweats occur.', 'Drenching sweats with fever, unexplained weight loss, or persistent symptoms need a doctor.', true),
('morning_sun_vitd', 'Short Morning Sunlight', 'low_vitamin_d', 'Low Vitamin D Signs', 'Skin makes vitamin D from sunlight, and short regular exposure helps maintain levels.', 'Spend 10-20 minutes outdoors in the morning with arms and face exposed when it is safe to do so.', 'Most days.', 'Note energy and mood over a month.', 'Sun exposure is the the body''s main natural source of vitamin D.', 'Deeper skin tones may need longer exposure. Avoid burning.', false),
('vitd_foods', 'Vitamin D Foods', 'low_vitamin_d', 'Low Vitamin D Signs', 'A few foods contribute vitamin D, though sunlight remains the main source.', 'Include oily fish, eggs, and fortified foods where available.', 'Regularly.', 'Track over a few months.', 'Oily fish and eggs are among the best dietary vitamin D sources.', NULL, true),
('ask_vitd_test', 'Ask About a Test Before Supplementing', 'low_vitamin_d', 'Low Vitamin D Signs', 'A blood test shows whether you are actually low and how much you need.', 'Ask a doctor for a vitamin D level check.', 'If you have persistent fatigue, bone or muscle aches.', 'Note results and dates.', 'Testing guides appropriate supplementation.', 'High-dose vitamin D can be harmful. Only supplement as advised.', true),
('give_time_bc', 'Give It Time and Keep a Log', 'birth_control_side_effects', 'Birth Control Side Effects', 'Many side effects such as spotting, nausea, and mood changes settle within the first 2-3 months.', 'Log symptoms daily for the first 3 months and note any patterns.', 'Daily during adjustment.', 'Use /log daily.', 'Side effects commonly improve as the body adjusts to a new method.', 'Severe leg pain, chest pain, sudden vision changes, or severe headaches are emergencies.', false),
('take_with_food_bc', 'Take at the Same Time, With Food if Nauseous', 'birth_control_side_effects', 'Birth Control Side Effects', 'Consistent timing keeps hormone levels steady, and food can ease nausea.', 'Take your pill at the same time daily, with a small snack if you feel queasy.', 'Daily.', 'Note nausea and spotting.', 'Consistent dosing reduces breakthrough bleeding, and food can reduce nausea.', NULL, true),
('talk_options_bc', 'Talk to Your Provider About Options', 'birth_control_side_effects', 'Birth Control Side Effects', 'If side effects continue past a few months, another method or dose may suit you better.', 'Bring your symptom log to your provider and ask about alternatives.', 'If symptoms persist beyond 3 months.', 'Bring your log.', 'There are many formulations and methods, and switching can resolve persistent side effects.', 'Do not stop suddenly without a backup method if you are avoiding pregnancy.', true),
('supportive_bra_breasts', 'Wear a Well-Fitting, Supportive Bra', 'fibrocystic_breasts', 'Lumpy, Cyclical Breast Feeling', 'Good support reduces breast movement, which eases cyclical soreness and lumpiness.', 'Choose a supportive bra, including a soft one for sleeping if helpful.', 'Daily, especially before your period.', 'Rate soreness by cycle day.', 'Supportive bras are a standard recommendation for cyclical breast pain.', NULL, false),
('compress_breasts', 'Warm or Cool Compress', 'fibrocystic_breasts', 'Lumpy, Cyclical Breast Feeling', 'Temperature can soothe tender, lumpy breast tissue.', 'Apply a warm or cool compress for 10-15 minutes.', 'As needed.', 'Note which helps most.', 'Simple compresses relieve breast tenderness for many people.', NULL, true),
('caffeine_breasts', 'See if Cutting Caffeine Helps', 'fibrocystic_breasts', 'Lumpy, Cyclical Breast Feeling', 'Some people find less caffeine eases cyclical breast discomfort, though evidence is mixed.', 'Try reducing coffee and cola for two cycles and compare.', 'Two cycles.', 'Track soreness each cycle.', 'Evidence is mixed, but many report benefit from trying it.', 'Any new lump that does not change with your cycle, or nipple discharge, needs a doctor.', true),
('heat_cyst', 'Heat Pad', 'ovarian_cyst_pain', 'One-Sided Pelvic Pain (Possible Cyst)', 'Warmth relaxes pelvic muscles and eases dull, one-sided aching.', 'Apply a heat pad to the painful side for 15-20 minutes.', 'During discomfort.', 'Note side and intensity.', 'Heat is a standard comfort measure for pelvic aching.', 'Sudden, severe pain with fever, vomiting, or faintness is an emergency.', false),
('rest_move_cyst', 'Rest and Gentle Movement', 'ovarian_cyst_pain', 'One-Sided Pelvic Pain (Possible Cyst)', 'Gentle movement keeps you comfortable while avoiding twisting or intense exercise during flares.', 'Choose walking or light stretching and rest when it hurts.', 'As needed.', 'Track pain against activity.', 'Rest and low-impact movement are typical advice for mild cyst-related discomfort.', NULL, true),
('track_pattern_cyst', 'Note the Side and Timing of Pain', 'ovarian_cyst_pain', 'One-Sided Pelvic Pain (Possible Cyst)', 'Pain that shows up mid-cycle or on one side repeatedly gives a doctor useful clues.', 'Log which side hurts, when in your cycle, and how long it lasts.', 'Each episode.', 'Use /log with notes.', 'Pain timing helps distinguish ovulation pain from cysts and other causes.', 'See a doctor if pain is recurring, severe, or comes with bloating that does not settle.', true),
('breathable_fabrics_sweat', 'Breathable Fabrics and Layers', 'excessive_sweating', 'Excessive Sweating', 'Natural, loose fabrics let sweat evaporate and reduce that soaked feeling.', 'Choose cotton, linen, or moisture-wicking layers and carry a spare top.', 'Daily.', 'Note which fabrics feel best.', 'Breathable fabrics improve evaporation and comfort.', NULL, false),
('night_antiperspirant_sweat', 'Apply Antiperspirant at Night', 'excessive_sweating', 'Excessive Sweating', 'Applied to dry skin at night, antiperspirant has more time to block sweat glands.', 'Apply a clinical-strength antiperspirant to clean, dry skin before bed.', 'Nightly.', 'Track sweating over 2 weeks.', 'Night application improves antiperspirant effectiveness.', 'Stop if it irritates your skin.', true),
('limit_triggers_sweat', 'Notice Your Triggers', 'excessive_sweating', 'Excessive Sweating', 'Caffeine, spicy food, and stress commonly bring on sweating.', 'Track when sweating peaks and cut back on obvious triggers.', 'Ongoing.', 'Log triggers for a week.', 'Common triggers include caffeine, spicy foods, and anxiety.', 'Sudden heavy sweating with weight loss, palpitations, or fever needs a doctor.', true),
('track_days_prolonged', 'Track Days and Flow Carefully', 'prolonged_periods', 'Periods Lasting Longer Than 7 Days', 'Exact dates and flow levels give a doctor a clear picture of what is happening.', 'Log the start, end, and flow intensity of every period in Ava.', 'Every period.', 'Use /log flow each day.', 'Bleeding duration is a key measure in assessing abnormal uterine bleeding.', 'A period lasting over 7 days regularly deserves a check-up.', false),
('iron_foods_prolonged', 'Iron-Rich Foods', 'prolonged_periods', 'Periods Lasting Longer Than 7 Days', 'Longer periods mean more blood loss, which can lower iron and cause tiredness.', 'Eat beans, leafy greens, or lean meat with vitamin C foods.', 'Daily during and after your period.', 'Track energy across cycles.', 'Longer bleeding raises the risk of iron depletion.', 'Ask for an iron test if fatigue persists.', true),
('book_checkup_prolonged', 'Book a Check-up', 'prolonged_periods', 'Periods Lasting Longer Than 7 Days', 'Prolonged bleeding can have treatable causes such as hormonal imbalance, fibroids, or polyps.', 'Bring your period log and ask what tests are appropriate.', 'Soon if it keeps happening.', 'Bring the logs.', 'Persistent prolonged bleeding warrants evaluation to find the cause.', 'Heavy bleeding with dizziness or a racing heart needs urgent care.', true),
('track_flow_light', 'Track Flow and Cycle Length', 'light_periods', 'Very Light or Scanty Periods', 'A log shows whether light periods are new, ongoing, or part of a wider pattern.', 'Record flow level and cycle length each month.', 'Every period.', 'Use /log flow.', 'Cycle logs help identify changes over time.', NULL, false),
('eat_enough_light', 'Eat Regularly and Enough', 'light_periods', 'Very Light or Scanty Periods', 'Not eating enough for your activity level can lighten or stop periods.', 'Aim for regular meals with enough energy, especially if you exercise a lot.', 'Daily.', 'Note changes over 2-3 cycles.', 'Low energy availability is a known cause of lighter or missed periods.', 'If periods stopped after intense exercise or restricting food, please talk to a doctor.', true),
('ask_hormonal_light', 'Ask About Hormonal Causes', 'light_periods', 'Very Light or Scanty Periods', 'Hormonal birth control, thyroid changes, and PCOS can all lighten periods.', 'Mention your flow changes to your doctor, along with any medication changes.', 'If it persists 3 or more cycles.', 'Note when the change began.', 'Several common hormonal factors alter flow.', NULL, true),
('kegels_pelvic', 'Pelvic Floor (Kegel) Exercises', 'pelvic_floor_weakness', 'Leaking When You Laugh, Cough or Sneeze', 'Strengthening the pelvic floor muscles improves bladder control over time.', 'Squeeze the muscles you would use to stop urine for 3-5 seconds, then relax. Repeat 10 times, three times a day.', 'Daily.', 'Track leaks per week.', 'Pelvic floor training is first-line treatment for stress urinary leakage.', NULL, false),
('bladder_irritants_pelvic', 'Cut Back on Bladder Irritants', 'pelvic_floor_weakness', 'Leaking When You Laugh, Cough or Sneeze', 'Caffeine and fizzy drinks can irritate the bladder and worsen urgency.', 'Reduce coffee, tea, and fizzy drinks for a couple of weeks and see if leaks lessen.', 'Daily.', 'Log drinks and leaks.', 'Caffeine is a known bladder irritant.', NULL, true),
('avoid_straining_pelvic', 'Avoid Straining and See a Pelvic Physio', 'pelvic_floor_weakness', 'Leaking When You Laugh, Cough or Sneeze', 'Constipation and heavy straining weaken the pelvic floor, and a specialist can tailor exercises.', 'Keep stools soft with fibre and water, and ask about pelvic floor physiotherapy.', 'Ongoing.', 'Note improvement over 6-8 weeks.', 'Pelvic floor physiotherapy has strong evidence for improving continence.', 'Blood in urine or pain when peeing needs a doctor.', true);
